import {mountExperiment} from '../model-kit/session.js';
import {attachCardDrag} from '../shared/drag.js';
import {definition} from '../../../embed/definitions/lab-consistency.js';
import {create,project,replayPolicy,describe,DIMENSIONS,MODES,SCENARIOS,e} from './model.js';
const options=(values,current)=>Object.entries(values).map(([value,label])=>`<option value="${e(value)}" ${value===current?'selected':''}>${e(label)}</option>`).join('');
const number=(id,label,value,max=120)=>`<label for="${id}">${e(label)}<input id="${id}" type="number" min="0" max="${max}" step="1" value="${value}" data-number="${id}"></label>`;
function render(s,{pinned}){const r=project(s),p=pinned&&replayPolicy(s,pinned);return `
  <div class="consistency-intro"><label for="scenario">Situation<select id="scenario">${options(Object.fromEntries(Object.entries(SCENARIOS).map(([k,v])=>[k,v.name])),s.scenario)}</select></label><p>${e(r.scenario.description)}</p></div>
  <section aria-labelledby="standards-title"><div class="section-intro"><h2 id="standards-title">Choose where consistency lives</h2><p>Drag a standard between columns, or use its “Apply as” menu. Every move changes the handoffs below.</p></div>
  <div class="standards-board">${Object.entries(MODES).map(([mode,label])=>`<section class="standard-lane" data-drop-id="${mode}" aria-label="${label}"><h3>${label}</h3><p class="lane-explanation">${mode==='local'?'Teams keep their own practice. Translate differences at each handoff.':mode==='mapped'?`Name the differences: ${s.mappingSetup} min setup per team; ${s.mappedTranslation} min per mismatched field.`:`Use the stated standard: ${s.setup} min setup per team; repair any local mismatch.`}</p><div class="standards-stack">${DIMENSIONS.filter(d=>s.policy[d.id]===mode).map(d=>`<article class="standard-token" data-drag-id="${d.id}"><button type="button" data-drag-handle aria-label="Drag ${d.label} to a policy column" class="standard-grip">↕ <strong>${d.label}</strong></button><p>${e(d.why)}</p><p class="proposed-standard">Common version: ${e(d.standard)}</p><label for="policy-${d.id}">Apply as<select id="policy-${d.id}" data-policy="${d.id}">${options(MODES,mode)}</select></label></article>`).join('')||'<p class="empty-lane">Move a standard here</p>'}</div></section>`).join('')}</div></section>
  <section aria-labelledby="handoffs-title" class="handoff-section"><h2 id="handoffs-title">Follow the work</h2><div class="consistency-verdict"><strong>${r.completed} / ${r.requested}</strong><span>handoffs fit the allowance<br>${r.blocked} wait</span><strong>${r.effort} min</strong><span>setup, translation<br>and workarounds</span></div>
  <div class="handoff-traces">${r.links.map((l,i)=>`<article class="handoff-trace"><p class="eyebrow">HANDOFF ${i+1}</p><h3>${e(l.from)} <span aria-hidden="true">→</span> ${e(l.to)}</h3><p class="handoff-outcome ${l.success?'passes':'waits'}">${l.completed} of ${l.count} pass · ${l.perHandoff} min each</p><p>Needs: ${l.needs.map(id=>DIMENSIONS.find(d=>d.id===id).label.toLowerCase()).join(', ')}.</p><ul>${l.gaps.map(g=>`<li>${g.dimension}: ${e(g.from)} → ${e(g.to)}<br><strong>${g.minutes} min</strong> ${g.mode==='mapped'?'using a named mapping':'direct translation'}</li>`).join('')||'<li>All required fields already match.</li>'}</ul><p class="trace-equation">${l.gaps.map(g=>g.minutes).join(' + ')||'0'} = ${l.perHandoff} min ${l.success?'≤':'>'} ${s.allowance} min allowance</p></article>`).join('')}</div>
  <p>Passing means the translation needed fits the per-handoff allowance. A waiting handoff consumes no translation time; its work remains undone.</p>
  ${p?`<div class="policy-comparison"><h3>Pinned policy, same situation</h3><p>Only the pinned standards are replayed. Both use the current teams, workloads and time assumptions.</p><table><thead><tr><th>Policy</th><th>Pass / requested</th><th>Setup</th><th>Translation</th><th>Workarounds</th></tr></thead><tbody><tr><th>Current</th><td>${r.completed} / ${r.requested}</td><td>${r.setup} min</td><td>${r.translation} min</td><td>${r.workaround} min</td></tr><tr><th>Pinned</th><td>${p.completed} / ${p.requested}</td><td>${p.setup} min</td><td>${p.translation} min</td><td>${p.workaround} min</td></tr></tbody></table><p>${DIMENSIONS.map(d=>`${d.label}: ${MODES[pinned.policy[d.id]]}`).join(' · ')}</p></div>`:''}</section>
  <details id="team-requirements" class="model-detail"><summary>What do the teams need?</summary><div class="local-requirements">${r.teams.map((t,i)=>`<article><h3>${e(t.name)}</h3><p>${e(t.work)} · ${t.jobs} items</p><dl>${DIMENSIONS.map((d,j)=>`<dt>${d.label}</dt><dd>${e(t.requirements[j])}</dd>`).join('')}</dl>${t.workarounds.length?`<ul>${t.workarounds.map(w=>`<li>${w.dimension}: ${t.jobs} items × ${w.perItem} min = <strong>${w.minutes} workaround min</strong>.</li>`).join('')}</ul>`:'<p>No local requirements need a workaround.</p>'}</article>`).join('')}</div></details>
  <details id="workload-assumptions" class="model-detail"><summary>Change workload and time assumptions</summary><p>One fictional working period. Counts are independent workload assumptions. Setup is charged once in this period, even when no handoffs need it.</p><div class="assumption-grid">${r.teams.map((t,i)=>number(`jobs-${i}`,`${t.name}: local items`,s.jobs[i],100)).join('')}${r.links.map((l,i)=>number(`handoffs-${i}`,`${l.from} → ${l.to}: handoffs`,s.handoffs[i],100)).join('')}${number('translation','Direct translation per mismatch (min)',s.translation,30)}${number('mappedTranslation','Mapped translation per mismatch (min)',s.mappedTranslation,30)}${number('allowance','Allowed translation per handoff (min)',s.allowance)}${number('setup','Common standard setup per team / dimension (min)',s.setup)}${number('mappingSetup','Mapping setup per team / dimension (min)',s.mappingSetup)}${DIMENSIONS.map((d,i)=>number(`workaround-${i}`,`${d.label}: workaround per local item (min)`,s.workaround[i],30)).join('')}</div></details>
  <details id="mechanism-notes" class="model-detail"><summary>Mechanism, limits and inspiration</summary><p>Each handoff declares the dimensions it needs. Different local values require translation. Named mappings reduce its assumed time; a common standard removes that difference. A common standard that conflicts with a team’s stated local requirement adds a workaround for every local item.</p><p>Effort = setup + translation for completed handoffs + local workarounds. The model assumes translation preserves meaning, workarounds preserve local needs, and the same cost applies across teams. It does not price waiting work, quality, adoption, power or learning. Lower effort with more waiting is not automatically better.</p><p>Try similar teams, then independent specialists. A standard can be redundant when people already match, and costly when teams rarely interact. Change the assumptions to challenge the result.</p><p>Inspired by John Cutler’s <a href="https://cutlefish.substack.com/p/tbm-421-minimally-viable-consistency">Minimally Viable Consistency</a>. This explicit accounting mechanism is an original illustrative model, not a measured version of his framework.</p></details>`;}
function bind({root,state:s,change}){const update=(mutate,message)=>{const next=structuredClone(s);mutate(next);change(next,message);};root.querySelector('#scenario').addEventListener('change',event=>change(create(event.target.value),'Loaded another fictional situation.'));
  root.querySelectorAll('[data-policy]').forEach(input=>input.addEventListener('change',()=>update(next=>next.policy[input.dataset.policy]=input.value,'Standard moved.')));
  root.querySelectorAll('[data-number]').forEach(input=>input.addEventListener('change',()=>{if(!input.checkValidity())return input.reportValidity();update(next=>{const [key,index]=input.dataset.number.split('-');if(index!==undefined)next[key][Number(index)]=Number(input.value);else next[key]=Number(input.value);},'Assumption changed; handoffs recalculated.');}));
  return attachCardDrag({root,onDrop:({itemId,dropId})=>update(next=>next.policy[itemId]=dropId,`${DIMENSIONS.find(d=>d.id===itemId).label} moved to ${MODES[dropId]}.`)});
}
await mountExperiment({route:'consistency',definition,render,bind,describe});
